433	export interface MonthPartitionBucket<T = SchoolTask> {
434	  monthNumber: number;
435	  academicYear: string;
436	  period: AcademicMonthPeriod;
437	  tasks: T[];
438	  priorOverdueBacklog: T[];
439	  stats: {
440	    totalTasks: number;
441	    completedTasks: number;
442	    inProgressTasks: number;
443	    overdueTasks: number;
444	    completionRate: number;
445	  };
446	}
447	
448	/**
449	 * Resolves the operational AcademicMonthPeriod for a given month number (1-12) and academic year.
450	 */
451	export function getAcademicMonthPeriod(
452	  monthNumber: number,
453	  academicYear?: string
454	): AcademicMonthPeriod {
455	  const yearStr = academicYear || getAcademicYear(getSystemReferenceDate());
456	  const startYear = parseInt(yearStr.split("-")[0], 10);
457	  const calendarYear = monthNumber >= 9 ? startYear : startYear + 1;
458	  return buildAcademicMonthPeriod(calendarYear, monthNumber, yearStr);
459	}
460	
461	function extractDateString(val: unknown): string | null {
462	  if (!val) return null;
463	  if (typeof val === "string") {
464	    const match = val.match(/^(\d{4}-\d{2}-\d{2})/);
465	    if (match) return match[1];
466	    const dt = new Date(val);
467	    if (!isNaN(dt.getTime())) {
468	      return new Intl.DateTimeFormat("en-CA", {
469	        timeZone: "Asia/Ho_Chi_Minh",
470	        year: "numeric",
471	        month: "2-digit",
472	        day: "2-digit",
473	      }).format(dt);
474	    }
475	    return null;
476	  }
477	  if (val instanceof Date && !isNaN(val.getTime())) {
478	    return new Intl.DateTimeFormat("en-CA", {
479	      timeZone: "Asia/Ho_Chi_Minh",
480	      year: "numeric",
481	      month: "2-digit",
482	      day: "2-digit",
483	    }).format(val);
484	  }
485	  return null;
486	}
487	
488	/**
489	 * Lọc các nhiệm vụ thuộc về tháng nghiệp vụ chỉ định theo chu kỳ 25 - 24.
490	 * Hỗ trợ "ALL" để giữ nguyên toàn bộ nhiệm vụ.
491	 * Cắt tỉa (prune) các subtask không thuộc tháng đang lọc để đảm bảo thống kê chính xác.
492	 */
493	export function filterTasksByAcademicMonthStrict<T extends { dueDate?: string | Date | null } = SchoolTask>(
494	  tasks: T[],
495	  month: number | "ALL",
496	  academicYear?: string
497	): T[] {
498	  if (month === "ALL") {
499	    return tasks;
500	  }
501	
502	  const period = getAcademicMonthPeriod(month, academicYear);
503	
504	  return tasks.reduce<T[]>((acc, task) => {
505	    const rawSubTasks = (task as any).subTasks;
506	    const hasSubTasks = Array.isArray(rawSubTasks);
507	
508	    // 1. Nếu có trường academicMonth tường minh, ưu tiên số 1
509	    if (typeof (task as any).academicMonth === "number") {
510	      if ((task as any).academicMonth === month) {
511	        if (hasSubTasks) {
512	          const prunedSubTasks = rawSubTasks.filter((st: any) => {
513	            const stDue = extractDateString(st.dueDate);
514	            if (!stDue) return true;
515	            return stDue >= period.startDate && stDue <= period.endDate;
516	          });
517	          acc.push({
518	            ...task,
519	            subTasks: prunedSubTasks,
520	            totalSubTasks: prunedSubTasks.length,
521	            completedSubTasks: prunedSubTasks.filter((st: any) => st.status === "COMPLETED").length,
522	          });
523	        } else {
524	          acc.push(task);
525	        }
526	      }
527	      return acc;
528	    }
529	
530	    const taskDue = extractDateString(task.dueDate);
531	    const dueInPeriod = Boolean(taskDue && taskDue >= period.startDate && taskDue <= period.endDate);
532	
533	    const subDueInPeriod =
534	      hasSubTasks &&
535	      rawSubTasks.some((st: any) => {
536	        const stDue = extractDateString(st.dueDate);
537	        return stDue && stDue >= period.startDate && stDue <= period.endDate;
538	      });
539	
540	    if (!dueInPeriod && !subDueInPeriod) {
541	      return acc;
542	    }
543	
544	    if (hasSubTasks) {
545	      const prunedSubTasks = rawSubTasks.filter((st: any) => {
546	        const stDue = extractDateString(st.dueDate);
547	        if (!stDue) return dueInPeriod;
548	        return stDue >= period.startDate && stDue <= period.endDate;
549	      });
550	
551	      const totalSubTasks = prunedSubTasks.length;
552	      const completedSubTasks = prunedSubTasks.filter((st: any) => st.status === "COMPLETED").length;
553	
554	      acc.push({
555	        ...task,
556	        subTasks: prunedSubTasks,
557	        totalSubTasks,
558	        completedSubTasks,
559	      });
560	    } else {
561	      acc.push(task);
562	    }
563	
564	    return acc;
565	  }, []);
566	}
567	
568	/**
569	 * Tính toán danh sách nợ đọng/tồn đọng (overdue backlog) từ các chu kỳ trước chưa hoàn thành.
570	 * Nhiệm vụ có hạn chót trước ngày bắt đầu của tháng nghiệp vụ hiện tại và chưa hoàn thành.
571	 */
572	export function computePriorOverdueBacklog<
573	  T extends { dueDate?: string | Date | null; status?: string } = SchoolTask,
574	>(
575	  tasks: T[],
576	  month: number,
577	  academicYear: string,
578	  referenceDate?: string
579	): T[] {
580	  const period = getAcademicMonthPeriod(month, academicYear);
581	  const cutoffDate =
582	    referenceDate && referenceDate < period.startDate ? referenceDate : period.startDate;
583	
584	  return tasks.filter((t) => {
585	    if (!t.dueDate) return false;
586	    if (t.status === "COMPLETED" || (t.status as string) === "CANCELLED") return false;
587	    const due = extractDateString(t.dueDate);
588	    if (!due) return false;
589	    return due < cutoffDate;
590	  });
591	}
592	
593	/**
594	 * Phân vùng dữ liệu nhiệm vụ cho một tháng học thuật cụ thể cùng với backlog từ trước và thống kê hoàn chỉnh.
595	 */
596	export function computeMonthPartitionBucket<
597	  T extends { dueDate?: string | Date | null; status?: string } = SchoolTask,
598	>(
599	  tasks: T[],
600	  month: number,
601	  academicYear: string,
602	  referenceDate?: string
603	): MonthPartitionBucket<T> {
604	  const period = getAcademicMonthPeriod(month, academicYear);
605	  const monthTasks = filterTasksByAcademicMonthStrict(tasks, month, academicYear);
606	  const priorOverdueBacklog = computePriorOverdueBacklog(tasks, month, academicYear, referenceDate);
607	
608	  const refDateStr = referenceDate
609	    ? extractDateString(referenceDate)
610	    : extractDateString(new Date());
611	
612	  const totalTasks = monthTasks.length;
613	  const completedTasks = monthTasks.filter((t) => t.status === "COMPLETED").length;
614	  const inProgressTasks = monthTasks.filter(
615	    (t) => t.status !== "COMPLETED" && (t.status as string) !== "CANCELLED"
616	  ).length;
617	
618	  const overdueTasks = monthTasks.filter((t) => {
619	    if (t.status === "COMPLETED" || (t.status as string) === "CANCELLED") return false;
620	    if ((t.status as string) === "OVERDUE") return true;
621	    const due = extractDateString(t.dueDate);
622	    return Boolean(due && refDateStr && due < refDateStr);
623	  }).length;
624	
625	  const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
626	
627	  return {
628	    monthNumber: month,
629	    academicYear,
630	    period,
631	    tasks: monthTasks,
632	    priorOverdueBacklog,
633	    stats: {
634	      totalTasks,
635	      completedTasks,
636	      inProgressTasks,
637	      overdueTasks,
638	      completionRate,
639	    },
640	  };
641	}
642	
