import { test, describe } from "node:test";
import assert from "node:assert/strict";
import {
  getAcademicMonthInfo,
  getAcademicYear,
  isOperationalMonthBoundary,
  parseDateParts,
} from "../../src/lib/academic-calendar";

describe("Academic Calendar Boundary & Timezone Tests", () => {
  describe("Requirement 1: Boundary Inclusivity & Timezone Offsets", () => {
    test("maps cycle end boundary (2026-08-24) to Month 8 of previous academic year", () => {
      const info = getAcademicMonthInfo("2026-08-24");
      assert.strictEqual(info.monthNumber, 8);
      assert.strictEqual(info.academicYear, "2025-2026");
      assert.strictEqual(info.startDate, "2026-07-25");
      assert.strictEqual(info.endDate, "2026-08-24");
    });

    test("maps cycle start boundary (2026-08-25) to Month 9 of new academic year", () => {
      const info = getAcademicMonthInfo("2026-08-25");
      assert.strictEqual(info.monthNumber, 9);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-08-25");
      assert.strictEqual(info.endDate, "2026-09-24");
    });

    test("maps month end boundary (2026-09-24) inclusively to Month 9", () => {
      const info = getAcademicMonthInfo("2026-09-24");
      assert.strictEqual(info.monthNumber, 9);
      assert.strictEqual(info.academicYear, "2026-2027");
    });

    test("maps month start boundary (2026-09-25) to Month 10", () => {
      const info = getAcademicMonthInfo("2026-09-25");
      assert.strictEqual(info.monthNumber, 10);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-09-25");
      assert.strictEqual(info.endDate, "2026-10-24");
    });

    test("maps year rollover month start (2026-12-25) to Month 1 of 2027", () => {
      const info = getAcademicMonthInfo("2026-12-25");
      assert.strictEqual(info.monthNumber, 1);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-12-25");
      assert.strictEqual(info.endDate, "2027-01-24");
    });

    test("maps year rollover month end (2027-01-24) to Month 1 of 2027", () => {
      const info = getAcademicMonthInfo("2027-01-24");
      assert.strictEqual(info.monthNumber, 1);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-12-25");
      assert.strictEqual(info.endDate, "2027-01-24");
    });

    test("handles ISO string with ICT timezone offset (+07:00) without day shift", () => {
      const dateStr = "2026-08-25T00:00:00+07:00";
      const parts = parseDateParts(dateStr);
      assert.deepStrictEqual(parts, { year: 2026, month: 8, day: 25 });

      const info = getAcademicMonthInfo(dateStr);
      assert.strictEqual(info.monthNumber, 9);
      assert.strictEqual(info.academicYear, "2026-2027");
    });

    test("handles ISO UTC timestamp equivalent to ICT midnight without shifting to previous day", () => {
      // 2026-08-24T17:00:00.000Z is 2026-08-25 00:00:00 in Asia/Ho_Chi_Minh (+07:00)
      const utcStr = "2026-08-24T17:00:00.000Z";
      const parts = parseDateParts(utcStr);
      assert.deepStrictEqual(parts, { year: 2026, month: 8, day: 25 });

      const info = getAcademicMonthInfo(utcStr);
      assert.strictEqual(info.monthNumber, 9);
      assert.strictEqual(info.academicYear, "2026-2027");
    });

    test("handles ISO UTC timestamp right before ICT midnight as previous day", () => {
      // 2026-08-24T16:59:59.000Z is 2026-08-24 23:59:59 in Asia/Ho_Chi_Minh (+07:00)
      const utcStr = "2026-08-24T16:59:59.000Z";
      const parts = parseDateParts(utcStr);
      assert.deepStrictEqual(parts, { year: 2026, month: 8, day: 24 });

      const info = getAcademicMonthInfo(utcStr);
      assert.strictEqual(info.monthNumber, 8);
      assert.strictEqual(info.academicYear, "2025-2026");
    });
  });

  describe("Requirement 2: isOperationalMonthBoundary helper & Leap Year tests", () => {
    test("identifies 2026-08-24 as operational cycle end boundary", () => {
      const boundary = isOperationalMonthBoundary("2026-08-24");
      assert.deepStrictEqual(boundary, { isStart: false, isEnd: true });
    });

    test("identifies 2026-08-25 as operational cycle start boundary", () => {
      const boundary = isOperationalMonthBoundary("2026-08-25");
      assert.deepStrictEqual(boundary, { isStart: true, isEnd: false });
    });

    test("identifies boundary with Date objects and timezone strings", () => {
      assert.deepStrictEqual(isOperationalMonthBoundary("2026-08-25T00:00:00+07:00"), {
        isStart: true,
        isEnd: false,
      });
      assert.deepStrictEqual(isOperationalMonthBoundary(new Date("2026-08-24T17:00:00Z")), {
        isStart: true,
        isEnd: false,
      });
      assert.deepStrictEqual(isOperationalMonthBoundary("2026-09-24T23:59:59+07:00"), {
        isStart: false,
        isEnd: true,
      });
    });

    test("returns false for non-boundary dates", () => {
      assert.deepStrictEqual(isOperationalMonthBoundary("2026-08-26"), {
        isStart: false,
        isEnd: false,
      });
      assert.deepStrictEqual(isOperationalMonthBoundary("2026-09-01"), {
        isStart: false,
        isEnd: false,
      });
      assert.deepStrictEqual(isOperationalMonthBoundary("2026-09-23"), {
        isStart: false,
        isEnd: false,
      });
    });

    test("handles invalid inputs gracefully", () => {
      assert.deepStrictEqual(isOperationalMonthBoundary("invalid-date"), {
        isStart: false,
        isEnd: false,
      });
      assert.deepStrictEqual(isOperationalMonthBoundary(null as any), {
        isStart: false,
        isEnd: false,
      });
      assert.deepStrictEqual(isOperationalMonthBoundary(undefined as any), {
        isStart: false,
        isEnd: false,
      });
    });

    test("handles leap-year February transitions (2028)", () => {
      // 2028 is a leap year (Feb 1 to Feb 29)
      // Tháng 2 runs from 2028-01-25 to 2028-02-24
      const feb24 = isOperationalMonthBoundary("2028-02-24");
      assert.deepStrictEqual(feb24, { isStart: false, isEnd: true });

      const infoFeb24 = getAcademicMonthInfo("2028-02-24");
      assert.strictEqual(infoFeb24.monthNumber, 2);
      assert.strictEqual(infoFeb24.academicYear, "2027-2028");

      // Tháng 3 runs from 2028-02-25 to 2028-03-24
      const feb25 = isOperationalMonthBoundary("2028-02-25");
      assert.deepStrictEqual(feb25, { isStart: true, isEnd: false });

      const infoFeb25 = getAcademicMonthInfo("2028-02-25");
      assert.strictEqual(infoFeb25.monthNumber, 3);
      assert.strictEqual(infoFeb25.academicYear, "2027-2028");
      assert.strictEqual(infoFeb25.startDate, "2028-02-25");
      assert.strictEqual(infoFeb25.endDate, "2028-03-24");

      // Feb 29 in leap year falls within Tháng 3 (2028-02-25 to 2028-03-24)
      const feb29 = isOperationalMonthBoundary("2028-02-29");
      assert.deepStrictEqual(feb29, { isStart: false, isEnd: false });

      const infoFeb29 = getAcademicMonthInfo("2028-02-29");
      assert.strictEqual(infoFeb29.monthNumber, 3);
      assert.strictEqual(infoFeb29.academicYear, "2027-2028");
    });

    test("handles non-leap-year February transitions (2027)", () => {
      const feb24 = isOperationalMonthBoundary("2027-02-24");
      assert.deepStrictEqual(feb24, { isStart: false, isEnd: true });

      const feb25 = isOperationalMonthBoundary("2027-02-25");
      assert.deepStrictEqual(feb25, { isStart: true, isEnd: false });

      const feb28 = isOperationalMonthBoundary("2027-02-28");
      assert.deepStrictEqual(feb28, { isStart: false, isEnd: false });

      const infoFeb28 = getAcademicMonthInfo("2027-02-28");
      assert.strictEqual(infoFeb28.monthNumber, 3);
      assert.strictEqual(infoFeb28.academicYear, "2026-2027");
    });
  });
});

