import { test, describe } from "node:test";
import assert from "node:assert/strict";
import {
  getAcademicMonthInfo,
  getAcademicYear,
  isOperationalMonthBoundary,
  parseDateParts,
} from "../../src/lib/academic-calendar";

describe("Academic Calendar Boundary & Timezone Tests", () => {
  describe("Requirement 1: Boundary Inclusivity & Timezone Offsets", () => {
    test("maps cycle end boundary (2026-08-24) to Month 8 of previous academic year", () => {
      const info = getAcademicMonthInfo("2026-08-24");
      assert.strictEqual(info.monthNumber, 8);
      assert.strictEqual(info.academicYear, "2025-2026");
      assert.strictEqual(info.startDate, "2026-07-25");
      assert.strictEqual(info.endDate, "2026-08-24");
    });

    test("maps cycle start boundary (2026-08-25) to Month 9 of new academic year", () => {
      const info = getAcademicMonthInfo("2026-08-25");
      assert.strictEqual(info.monthNumber, 9);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-08-25");
      assert.strictEqual(info.endDate, "2026-09-24");
    });

    test("maps month end boundary (2026-09-24) inclusively to Month 9", () => {
      const info = getAcademicMonthInfo("2026-09-24");
      assert.strictEqual(info.monthNumber, 9);
      assert.strictEqual(info.academicYear, "2026-2027");
    });

    test("maps month start boundary (2026-09-25) to Month 10", () => {
      const info = getAcademicMonthInfo("2026-09-25");
      assert.strictEqual(info.monthNumber, 10);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-09-25");
      assert.strictEqual(info.endDate, "2026-10-24");
    });

    test("maps year rollover month start (2026-12-25) to Month 1 of 2027", () => {
      const info = getAcademicMonthInfo("2026-12-25");
      assert.strictEqual(info.monthNumber, 1);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-12-25");
      assert.strictEqual(info.endDate, "2027-01-24");
    });

    test("maps year rollover month end (2027-01-24) to Month 1 of 2027", () => {
      const info = getAcademicMonthInfo("2027-01-24");
      assert.strictEqual(info.monthNumber, 1);
      assert.strictEqual(info.academicYear, "2026-2027");
      assert.strictEqual(info.startDate, "2026-12-25");
      assert.strictEqual(info.endDate, "2027-01-24");
    });

    test("handles ISO string with ICT timezone offset (+07:00) without day shift", () => {
      const dateStr = "2026-08-25T00:00:00+07:00";
      const parts = parseDateParts(dateStr);
      assert.deepStrictEqual(parts, { year: 2026, month: 8, day: 25 });

      const info = getAcademicMonthInfo(dateStr);
      assert.strictEqual(info.monthNumber, 9);
      assert.strictEqual(info.academicYear, "2026-2027");
