        if (parts[1] >= 1 && parts[1] <= 12 && parts[2] >= 1 && parts[2] <= 31) {
          return {
            year: parts[0],
            month: parts[1],
            day: parts[2],
          };
        }
      }
      return null;
    }
    const d = new Date(trimmed);
    if (isNaN(d.getTime())) return null;
    return parseDateParts(d);
  }
  if (dateInput instanceof Date) {
    if (isNaN(dateInput.getTime())) return null;
    const formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Ho_Chi_Minh",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    const parts = formatter.formatToParts(dateInput);
    const y = parts.find((p) => p.type === "year")?.value;
    const m = parts.find((p) => p.type === "month")?.value;
    const d = parts.find((p) => p.type === "day")?.value;
    if (!y || !m || !d) return null;
    return {
      year: parseInt(y, 10),
      month: parseInt(m, 10),
      day: parseInt(d, 10),
    };
  }
  return null;
}

/**
 * Kiểm tra xem một ngày có phải là mốc ranh giới chu kỳ tháng vận hành học vụ hay không.
 * - isStart: true nếu ngày là 25 (ngày bắt đầu tháng vận hành mới)
 * - isEnd: true nếu ngày là 24 (ngày kết thúc tháng vận hành hiện tại)
 */
export function isOperationalMonthBoundary(date: Date | string): { isStart: boolean; isEnd: boolean } {
  const parts = parseDateParts(date);
  if (!parts) {
    return { isStart: false, isEnd: false };
  }
  return {
    isStart: parts.day === 25,
    isEnd: parts.day === 24,
  };
}

